using Godot;
using System;
using System.Linq;
using System.Collections.Generic;
using System.Buffers.Binary;
using Settings=Godot.Collections.Dictionary;
public partial class ActorAudioRecorderOperations:RefCounted
{
    private static Variant Get(Settings values,string key,Variant fallback=default)=>values.TryGetValue(key,out var value)?value:fallback;
    private static T? Object<T>(Node owner,string name) where T:GodotObject=>owner.Get(name).AsGodotObject() as T;
    public Settings read_preferences(){using var config=new ConfigFile();config.Load("user://editor_audio_settings.cfg");return new Settings{["record_mic"]=config.GetValue("microphone","record_mic",true).AsBool(),["record_system"]=config.GetValue("microphone","record_system",false).AsBool(),["record_timeline"]=config.GetValue("microphone","record_timeline",false).AsBool(),["device"]=config.GetValue("microphone","device","Default").AsString(),["gain_db"]=config.GetValue("microphone","gain_db",0.0).AsDouble(),["mono"]=config.GetValue("microphone","mono",false).AsBool()};}
    public void write_preferences(Settings values){using var config=new ConfigFile();foreach(var entry in values)config.SetValue("microphone",entry.Key.AsString(),entry.Value);config.Save("user://editor_audio_settings.cfg");}
    public Settings requested_preferences(Node owner){var values=owner.Get("preferences_override").AsGodotDictionary();return (values.Count==0?read_preferences():values).Duplicate(true);}
    public bool monitors_timeline(Settings values)=>Get(values,"monitor_timeline",Get(values,"record_timeline",false)).AsBool();
    public bool backing_requested(Settings values)=>Get(values,"record_timeline",false).AsBool()||monitors_timeline(values);
    public string preference_error(Settings values){bool backing=Get(values,"record_timeline",false).AsBool();if(monitors_timeline(values)&&Get(values,"record_system",false).AsBool()&&!backing)return "System capture includes the audio you hear. Turn off System in the recording dropdown for a dry overdub, or enable Include backing in take.";if(!Get(values,"record_mic",false).AsBool()&&!Get(values,"record_system",false).AsBool()&&!backing)return "Select microphone, system, timeline audio, or a combination in the recording dropdown. Hearing backing alone is not a recording source.";return "";}
    public string capture_error(Node owner){foreach(string key in new[]{"_mic_writer","_timeline_writer"}){var writer=Object<RefCounted>(owner,key);if(writer==null)continue;string error=writer.Call("error").AsString();if(error.Length>0)return error;}return owner.Get("_capture_problem").AsString();}
    public void drain_to_writer(AudioEffectCapture? input,RefCounted? writer){if(input==null||writer==null)return;if(input.GetDiscardedFrames()>0)writer.Call("fail","Audio capture overran its half-second ring. The captured prefix was retained; this take is partial.");int remaining=Math.Min(input.GetFramesAvailable(),96000);while(remaining>0){int count=Math.Min(remaining,16384);writer.Call("append_frames",input.GetBuffer(count));remaining-=count;}}
    public void convert_to_mono(AudioStreamWav stream){if(!stream.Stereo)return;var source=stream.Data;var data=new byte[source.Length/4*2];for(int frame=0;frame<source.Length/4;frame++){int sum=BinaryPrimitives.ReadInt16LittleEndian(source.AsSpan(frame*4,2))+BinaryPrimitives.ReadInt16LittleEndian(source.AsSpan(frame*4+2,2));BinaryPrimitives.WriteInt16LittleEndian(data.AsSpan(frame*2,2),(short)(sum/2));}stream.Data=data;stream.Stereo=false;}
    public AudioStreamWav? mix_streams(AudioStreamWav? mic,AudioStreamWav? system){if(mic==null)return system;if(system==null)return mic;int rate=system.MixRate,frames=(int)(Math.Max(mic.GetLength(),system.GetLength())*rate);var bytes=new byte[checked(frames*4)];var micData=mic.Data;var systemData=system.Data;for(int frame=0;frame<frames;frame++){var sample=sample_data(micData,mic.MixRate,mic.Stereo,(double)frame/rate)+sample_data(systemData,system.MixRate,system.Stereo,(double)frame/rate);BinaryPrimitives.WriteInt16LittleEndian(bytes.AsSpan(frame*4,2),(short)Math.Clamp((int)(sample.X*32768),-32768,32767));BinaryPrimitives.WriteInt16LittleEndian(bytes.AsSpan(frame*4+2,2),(short)Math.Clamp((int)(sample.Y*32768),-32768,32767));}return new AudioStreamWav{Format=AudioStreamWav.FormatEnum.Format16Bits,Stereo=true,MixRate=rate,Data=bytes};}
    public Vector2 sample(AudioStreamWav stream,double time)=>sample_data(stream.Data,stream.MixRate,stream.Stereo,time);
    public Vector2 sample_data(byte[] data,int rate,bool stereo,double time){double position=time*rate;long index=(long)position;int channels=stereo?2:1,count=data.Length/(2*channels);if(index<0||index>=count)return Vector2.Zero;int frame=(int)index;Vector2 Read(int i)=>new Vector2(BinaryPrimitives.ReadInt16LittleEndian(data.AsSpan(i*channels*2,2)),BinaryPrimitives.ReadInt16LittleEndian(data.AsSpan((i*channels+channels-1)*2,2)));return Read(frame).Lerp(Read(Math.Min(frame+1,count-1)),(float)(position-frame))/32768;}
    private static void Peaks(Node owner,Vector2[] samples,int framesPerPeak,string peakName,string frameName,string historyName){float peak=owner.Get(peakName).AsSingle();int frames=owner.Get(frameName).AsInt32();var history=new List<float>(owner.Get(historyName).AsFloat32Array());foreach(var sample in samples){peak=Math.Max(peak,Math.Max(Math.Abs(sample.X),Math.Abs(sample.Y)));frames++;if(frames>=framesPerPeak){history.Add(peak);peak=0;frames=0;}}owner.Set(peakName,peak);owner.Set(frameName,frames);owner.Set(historyName,history.ToArray());}
    public void process(Node owner,double delta)
    {
        if(!owner.Get("recording").AsBool())return;var capture=Object<AudioEffectCapture>(owner,"capture");var timeline=Object<AudioEffectCapture>(owner,"timeline_capture");var system=Object<Node>(owner,"system_capture");if(owner.Get("disk_backed").AsBool()){drain_to_writer(capture,Object<RefCounted>(owner,"_mic_writer"));drain_to_writer(timeline,Object<RefCounted>(owner,"_timeline_writer"));double elapsed=owner.Get("_system_check_elapsed").AsDouble()+delta;owner.Set("_system_check_elapsed",elapsed);if(system!=null&&elapsed>=1){owner.Set("_system_check_elapsed",0.0);int pid=system.Get("pid").AsInt32();if(pid>0&&!OS.IsProcessRunning(pid))owner.Set("_capture_problem","System capture stopped unexpectedly. Any checkpointed source was retained.");using var file=Godot.FileAccess.Open(system.Get("output_path").AsString(),Godot.FileAccess.ModeFlags.Read);if(file!=null&&file.GetLength()>2UL*1024*1024*1024-44)owner.Set("_capture_problem","The 2 GiB system-capture limit was reached. Capture sources were retained.");}return;}
        if(system!=null)Peaks(owner,system.Call("samples").AsVector2Array(),system.Get("rate").AsInt32()/100,"_system_peak","_system_frames","_system_peaks");Peaks(owner,capture!=null&&capture.GetFramesAvailable()>0?capture.GetBuffer(capture.GetFramesAvailable()):Array.Empty<Vector2>(),(int)(AudioServer.GetMixRate()/100),"_peak","_peak_frames","_mic_peaks");Peaks(owner,timeline!=null&&timeline.GetFramesAvailable()>0?timeline.GetBuffer(timeline.GetFramesAvailable()):Array.Empty<Vector2>(),(int)(AudioServer.GetMixRate()/100),"_timeline_peak","_timeline_frames","_timeline_peaks");var combined=new List<float>(owner.Get("_mic_peaks").AsFloat32Array());foreach(string key in new[]{"_system_peaks","_timeline_peaks"}){var source=owner.Get(key).AsFloat32Array();while(combined.Count<source.Length)combined.Add(0);for(int i=0;i<source.Length;i++)combined[i]=Math.Min(1,combined[i]+source[i]);}owner.Set("peaks",combined.ToArray());
    }
    public void cleanup(Node owner,Settings active)
    {
        owner.Set("recording",false);active.Remove(owner.Get("_take_directory").AsString().Replace('\\','/').SimplifyPath());foreach(string key in new[]{"_mic_writer","_timeline_writer"})Object<RefCounted>(owner,key)?.Call("request_finish");foreach(string key in new[]{"_mic_writer","_timeline_writer"})Object<RefCounted>(owner,key)?.Call("finish");owner.Set("_mic_writer",default(Variant));owner.Set("_timeline_writer",default(Variant));owner.Set("_take_directory","");Object<AudioEffectRecord>(owner,"effect")?.SetRecordingActive(false);Object<AudioEffectRecord>(owner,"timeline_effect")?.SetRecordingActive(false);var system=Object<Node>(owner,"system_capture");if(system!=null){system.Call("cleanup");system.QueueFree();owner.Set("system_capture",default(Variant));}var player=Object<AudioStreamPlayer>(owner,"player");if(GodotObject.IsInstanceValid(player)){player!.Stop();player.QueueFree();}owner.Set("player",default(Variant));foreach(string name in new[]{"bus_name","timeline_bus_name"}){int bus=AudioServer.GetBusIndex(owner.Get(name).AsString());if(bus>0)AudioServer.RemoveBus(bus);owner.Set(name,"");}foreach(string key in new[]{"effect","capture","timeline_effect","timeline_capture"})owner.Set(key,default(Variant));owner.Set("record_timeline",false);owner.Set("monitor_timeline",false);
    }
}
